import{s as e}from"./index-B3CZxWrq.js";var t={title:`한푼 개인정보 처리방침`,byline:`Oct 24, 2026 · @Calsweet`,introduction:`한푼(이하 '서비스')은 「개인정보 보호법」 제30조에 따라 정보주체의 개인정보를 보호하고 이와 관련한 고충을 신속하고 원활하게 처리하기 위하여 다음과 같이 개인정보 처리방침을 수립·공개합니다.`,sections:[{title:`제1조 (개인정보의 처리 목적)`,blocks:[{type:`paragraph`,text:`서비스는 다음의 목적을 위하여 개인정보를 처리합니다. 처리한 개인정보는 다음 목적 이외의 용도로 이용되지 않으며, 목적이 변경되는 경우 「개인정보 보호법」 제18조에 따라 별도의 동의를 받는 등 필요한 조치를 이행합니다.`},{type:`list`,items:[`회원 가입 및 관리: 회원제 서비스 제공에 따른 본인 식별·인증, 회원자격 유지·관리, 부정 이용 방지, 각종 고지·통지`,`서비스 제공: 서비스 내 기능 제공, 이용자가 작성한 콘텐츠의 저장 및 표시`,`고충 처리: 민원인의 신원 확인, 문의사항 확인, 처리 결과 통보`,`서비스 개선 및 보안: 접속 빈도 파악, 서비스 이용 통계, 오류 분석 및 부정 이용 탐지`]}]},{title:`제2조 (처리하는 개인정보의 항목)`,blocks:[{type:`table`,headers:[`구분`,`수집 항목`,`수집 방법`],rows:[[`회원가입(필수)`,`이메일 주소, 비밀번호(암호화 저장), 닉네임`,`회원가입 화면 입력`],[`소셜 로그인 이용 시`,`소셜 계정 식별자, 이메일 주소, 프로필 이름`,`해당 소셜 서비스 연동`],[`서비스 이용 과정`,`이용자가 작성·등록한 콘텐츠`,`서비스 이용 중 입력`],[`자동 생성·수집`,`접속 IP 주소, 접속 일시, 서비스 이용 기록, 기기·브라우저 정보, 인증 토큰`,`서비스 이용 시 자동 생성`]]}]},{title:`제3조 (개인정보의 처리 및 보유 기간)`,blocks:[{type:`paragraph`,text:`서비스는 법령에 따른 보유·이용 기간 또는 정보주체로부터 동의받은 기간 내에서 개인정보를 처리·보유합니다.`},{type:`list`,items:[`회원 정보: 회원 탈퇴 시까지. 다만 부정 이용 방지를 위해 탈퇴 후 30일간 보관 후 파기합니다.`,`서비스 이용 기록 및 접속 로그: 「통신비밀보호법」에 따라 3개월`,`소비자 불만 또는 분쟁 처리 기록: 「전자상거래 등에서의 소비자보호에 관한 법률」에 따라 3년(해당 시)`,`관계 법령 위반에 따른 수사·조사가 진행 중인 경우: 해당 수사·조사 종료 시까지`]}]},{title:`제4조 (개인정보의 제3자 제공)`,blocks:[{type:`paragraph`,text:`서비스는 정보주체의 개인정보를 제1조에서 명시한 범위 내에서만 처리하며, 정보주체의 동의 또는 법률의 특별한 규정 등 「개인정보 보호법」 제17조 및 제18조에 해당하는 경우에만 제3자에게 제공합니다. 현재 서비스는 개인정보를 제3자에게 제공하지 않습니다.`}]},{title:`제5조 (개인정보 처리의 위탁)`,blocks:[{type:`paragraph`,text:`서비스는 원활한 서비스 제공을 위하여 다음과 같이 개인정보 처리업무를 위탁하고 있습니다.`},{type:`table`,headers:[`수탁자`,`위탁 업무 내용`],rows:[[`Supabase, Inc.`,`회원 인증, 데이터베이스 호스팅 및 데이터 저장·관리`]]},{type:`paragraph`,text:`서비스는 위탁계약 체결 시 「개인정보 보호법」 제26조에 따라 위탁업무 수행 목적 외 개인정보 처리 금지, 기술적·관리적 보호조치, 재위탁 제한, 수탁자에 대한 관리·감독, 손해배상 등 책임에 관한 사항을 계약서 등 문서에 명시하고, 수탁자가 개인정보를 안전하게 처리하는지 감독합니다. 위탁업무의 내용이나 수탁자가 변경될 경우 본 개인정보 처리방침을 통하여 공개합니다.`}]},{title:`제6조 (개인정보의 국외 이전)`,blocks:[{type:`paragraph`,text:`서비스는 「개인정보 보호법」 제28조의8에 따라 다음과 같이 개인정보를 국외로 이전하여 처리합니다.`},{type:`table`,headers:[`항목`,`내용`],rows:[[`이전받는 자`,`Supabase, Inc.`],[`이전되는 국가`,`미국 (데이터 저장 리전: [프로젝트 리전 기재])`],[`이전 일시 및 방법`,`서비스 이용 시점에 네트워크를 통한 전송`],[`이전 항목`,`제2조에 명시된 개인정보 전체`],[`이전 목적`,`회원 인증, 데이터베이스 호스팅 및 데이터 저장·관리`],[`보유·이용 기간`,`회원 탈퇴 또는 위탁계약 종료 시까지`],[`이전받는 자의 연락처`,`[Supabase 개인정보 문의처 기재]`]]},{type:`paragraph`,text:`정보주체는 국외 이전을 거부할 수 있습니다. 다만 위 업무는 서비스 제공에 필수적이므로, 거부하는 경우 회원가입 및 서비스 이용이 불가능합니다. 거부 방법: 회원 탈퇴 또는 제14조의 개인정보 보호책임자에게 요청`}]},{title:`제7조 (개인정보의 파기 절차 및 방법)`,blocks:[{type:`paragraph`,text:`서비스는 개인정보 보유기간의 경과, 처리목적 달성 등 개인정보가 불필요하게 되었을 때에는 지체 없이 해당 개인정보를 파기합니다.`},{type:`list`,items:[`파기 절차: 파기 사유가 발생한 개인정보를 선정하고, 개인정보 보호책임자의 승인을 받아 파기합니다.`,`파기 방법: 전자적 파일 형태의 정보는 복구·재생할 수 없는 기술적 방법으로 삭제하며, 종이 문서는 분쇄하거나 소각합니다.`,`법령에 따라 보존하는 경우: 다른 법령에 따라 개인정보를 계속 보존해야 하는 경우 해당 개인정보를 별도의 데이터베이스로 옮기거나 보관 장소를 달리하여 보존합니다.`]}]},{title:`제8조 (정보주체와 법정대리인의 권리·의무 및 행사방법)`,blocks:[{type:`list`,items:[`정보주체는 서비스에 대해 언제든지 개인정보 열람, 정정·삭제, 처리정지 및 동의 철회 요구 등의 권리를 행사할 수 있습니다.`,`권리 행사는 서비스 내 설정 메뉴 또는 제14조의 연락처로 서면, 전자우편 등을 통해 할 수 있으며, 서비스는 이에 대해 지체 없이(10일 이내) 조치합니다.`,`권리 행사는 정보주체의 법정대리인이나 위임을 받은 자 등 대리인을 통하여 할 수 있으며, 이 경우 위임장을 제출해야 합니다.`,`개인정보 열람 및 처리정지 요구는 「개인정보 보호법」 제35조 제4항, 제37조 제2항에 의하여 제한될 수 있습니다.`,`다른 법령에서 해당 개인정보가 수집 대상으로 명시된 경우 그 삭제를 요구할 수 없습니다.`,`서비스는 권리 행사를 한 자가 본인이거나 정당한 대리인인지를 확인합니다.`]}]},{title:`제9조 (만 14세 미만 아동의 개인정보 처리)`,blocks:[{type:`list`,items:[`서비스는 만 14세 미만 아동의 개인정보를 처리하기 위하여 동의가 필요한 경우 「개인정보 보호법」 제22조의2에 따라 법정대리인의 동의를 받습니다.`,`법정대리인의 동의를 받기 위하여 필요한 최소한의 정보(법정대리인의 성명, 연락처)를 아동으로부터 직접 수집할 수 있습니다.`,`법정대리인의 동의가 확인되지 않은 만 14세 미만 아동의 개인정보는 지체 없이 파기합니다.`]}]},{title:`제10조 (개인정보의 안전성 확보조치)`,blocks:[{type:`paragraph`,text:`서비스는 개인정보의 안전성 확보를 위해 다음과 같은 조치를 취하고 있습니다.`},{type:`list`,items:[`관리적 조치: 개인정보 취급자 최소화 및 내부관리계획 수립·시행`,`기술적 조치: 비밀번호의 일방향 암호화 저장, 전송 구간 암호화(HTTPS/TLS), 데이터베이스 행 수준 보안(RLS)을 통한 접근 권한 제한, 접속기록 보관`,`물리적 조치: 데이터센터 물리적 보안은 수탁자(Supabase, Inc.)의 보안 정책 및 인증 체계에 따름`]}]},{title:`제11조 (개인정보 자동 수집 장치의 설치·운영 및 거부에 관한 사항)`,blocks:[{type:`list`,items:[`서비스는 로그인 상태 유지 등 서비스 제공을 위하여 쿠키 및 브라우저 로컬 스토리지(이하 '쿠키 등')에 인증 정보를 저장합니다.`,`이용자는 웹 브라우저 설정을 통해 쿠키 등의 저장을 거부하거나 삭제할 수 있습니다. 예: Chrome의 경우 설정 > 개인정보 및 보안 > 쿠키 및 기타 사이트 데이터`,`쿠키 등의 저장을 거부할 경우 로그인이 필요한 서비스 이용에 어려움이 발생할 수 있습니다.`]}]},{title:`제12조 (행태정보의 수집·이용 및 거부 등에 관한 사항)`,blocks:[{type:`paragraph`,text:`서비스는 온라인 맞춤형 광고 등을 위한 행태정보를 수집·이용·제공하지 않습니다.`}]},{title:`제13조 (가명정보의 처리)`,blocks:[{type:`paragraph`,text:`서비스는 통계작성, 과학적 연구, 공익적 기록보존 등을 위하여 가명정보를 처리하지 않습니다. 향후 처리하는 경우 그 목적, 항목, 기간 등을 본 방침을 통해 공개합니다.`}]},{title:`제14조 (개인정보 보호책임자)`,blocks:[{type:`paragraph`,text:`서비스는 개인정보 처리에 관한 업무를 총괄해서 책임지고, 개인정보 처리와 관련한 정보주체의 불만처리 및 피해구제 등을 위하여 아래와 같이 개인정보 보호책임자를 지정하고 있습니다.`},{type:`table`,headers:[`구분`,`내용`],rows:[[`성명`,`[성명 기재]`],[`직책`,`운영자`],[`이메일`,`[미정]`]]},{type:`paragraph`,text:`정보주체는 서비스 이용 중 발생한 모든 개인정보 보호 관련 문의, 불만처리, 피해구제 등에 관한 사항을 개인정보 보호책임자에게 문의할 수 있으며, 서비스는 이에 대해 지체 없이 답변 및 처리합니다.`}]},{title:`제15조 (권익침해 구제방법)`,blocks:[{type:`paragraph`,text:`정보주체는 개인정보침해로 인한 구제를 받기 위하여 아래 기관에 분쟁해결이나 상담 등을 신청할 수 있습니다.`},{type:`table`,headers:[`기관`,`연락처`],rows:[[`개인정보분쟁조정위원회`,`(국번없이) 1833-6972 / www.kopico.go.kr`],[`개인정보침해신고센터(한국인터넷진흥원)`,`(국번없이) 118 / privacy.kisa.or.kr`],[`대검찰청`,`(국번없이) 1301 / www.spo.go.kr`],[`경찰청`,`(국번없이) 182 / ecrm.police.go.kr`]]}]},{title:`제16조 (개인정보 처리방침의 변경)`,blocks:[{type:`list`,items:[`본 개인정보 처리방침은 2026년 [ ]월 [ ]일부터 적용됩니다.`,`내용의 추가, 삭제 및 수정이 있을 경우 시행일 최소 7일 전에 서비스 내 공지사항을 통해 고지합니다. 다만 이용자 권리의 중대한 변경이 발생할 때에는 최소 30일 전에 고지합니다.`]}]}],notes:{title:`작성 시 채울 항목`,items:[`제2조: 한푼이 실제로 수집하는 항목에 맞게 수정(소셜 로그인 미사용 시 해당 행 삭제)`,`제6조: Supabase 프로젝트 리전, Supabase 개인정보 문의처`,`제14조: 책임자 성명, 문의 이메일`,`제16조: 시행일`]}},n=e(),r=t;function i(){return(0,n.jsxs)(`article`,{className:`privacy-document`,children:[(0,n.jsxs)(`header`,{className:`privacy-heading`,children:[(0,n.jsx)(`h1`,{children:r.title}),(0,n.jsx)(`p`,{children:r.byline})]}),(0,n.jsx)(`p`,{children:r.introduction}),r.sections.map((e,t)=>(0,n.jsxs)(`section`,{"aria-labelledby":`policy-article-${t+1}`,children:[(0,n.jsx)(`h2`,{id:`policy-article-${t+1}`,children:e.title}),e.blocks.map((t,r)=>t.type===`paragraph`?(0,n.jsx)(`p`,{children:t.text},r):t.type===`list`?(0,n.jsx)(`ol`,{children:t.items.map(e=>(0,n.jsx)(`li`,{children:e},e))},r):(0,n.jsx)(`div`,{className:`privacy-table-wrap${t.headers.length===3?` privacy-table-wide`:``}`,tabIndex:t.headers.length===3?0:void 0,role:`region`,"aria-label":`${e.title} 표`,children:(0,n.jsxs)(`table`,{children:[(0,n.jsx)(`thead`,{children:(0,n.jsx)(`tr`,{children:t.headers.map(e=>(0,n.jsx)(`th`,{scope:`col`,children:e},e))})}),(0,n.jsx)(`tbody`,{children:t.rows.map((e,t)=>(0,n.jsx)(`tr`,{children:e.map((e,t)=>(0,n.jsx)(`td`,{children:e},t))},t))})]})},r))]},e.title)),(0,n.jsxs)(`section`,{className:`privacy-source-notes`,"aria-labelledby":`policy-source-notes`,children:[(0,n.jsx)(`h2`,{id:`policy-source-notes`,children:r.notes.title}),(0,n.jsx)(`ul`,{children:r.notes.items.map(e=>(0,n.jsx)(`li`,{children:e},e))})]}),(0,n.jsxs)(`nav`,{className:`privacy-document-links`,"aria-label":`개인정보 처리방침 문서`,children:[(0,n.jsx)(`a`,{href:`/privacy-policy.pdf`,download:`한푼 개인정보 처리방침.pdf`,children:`원본 PDF 다운로드`}),(0,n.jsx)(`a`,{href:`/privacy/`,children:`전체 페이지로 보기`})]})]})}export{i as PrivacyPolicy};